if (off == nullptr || *off == 0) {
    return 0;
}

uint32_t ctz = 0;
lfs_off_t val = *off;

if (sizeof(lfs_off_t) == 8) {
    uint64_t low = static_cast<uint64_t>(val);
    if (low == 0) {
        ctz = 64;
        val >>= 64; // This is conceptual; handled by the logic below
    } else {
        ctz = static_cast<uint32_t>(std::countr_zero(low));
    }
} else {
    uint32_t low = static_cast<uint32_t>(val);
    ctz = (low == 0) ? 32 : static_cast<uint32_t>(std::countr_zero(low));
}

*off = static_cast<lfs_off_t>(1) << ctz;
return ctz;
// END_CODE

